fn smallest_change(arr: Vec<i8>) -> usize {
    let n = arr.len();
    let mut count = 0;
    // Only need to check the first half of the array against its mirrored second half
    for i in 0..(n / 2) {
        if arr[i] != arr[n - 1 - i] {
            count += 1;
        }
    }
    count
}

